from copy import deepcopy
import math
from numbers import Real


class CallablePipeline:
    def __init__(self, model=None, loader=None, transformer=None):
        if model is None:
            if not callable(loader):
                raise TypeError("a callable loader is required")
            model = loader()
        if not callable(model):
            raise TypeError("model must be callable")
        if transformer is not None and not callable(transformer):
            raise TypeError("transformer must be callable")
        self._model = model
        self._transformer = transformer
        hook = getattr(model, "set_evaluation", None)
        if callable(hook):
            hook(True)

    @staticmethod
    def _valid_rows(rows):
        if not isinstance(rows, list):
            return False
        for row in rows:
            if not isinstance(row, list):
                return False
            for value in row:
                if (isinstance(value, bool) or not isinstance(value, Real)
                        or not math.isfinite(value)):
                    return False
        return True

    def predict(self, rows, transform=True):
        if not isinstance(transform, bool):
            raise TypeError("transform must be boolean")
        if not self._valid_rows(rows):
            raise ValueError("invalid rows")
        prepared = rows
        if transform and self._transformer is not None:
            prepared = self._transformer(prepared)
        return deepcopy(self._model(prepared))

    def output_width(self, input_width):
        if isinstance(input_width, bool) or not isinstance(input_width, int) or input_width < 0:
            raise ValueError("invalid input width")
        prediction = self.predict([[0.0] * input_width], transform=False)
        if (not isinstance(prediction, list) or len(prediction) != 1
                or not isinstance(prediction[0], list)):
            raise ValueError("invalid model output")
        return len(prediction[0])

